<?php
$id=(int)($_GET['id']??0);$stmt=db()->prepare("SELECT pr.*,p.patient_id,p.patient_code,p.full_name patient_name,p.date_of_birth,p.blood_group,p.phone,u.full_name doctor_name,d.specialization,d.qualification,dep.department_name,c.diagnosis,c.chief_complaint FROM prescriptions pr JOIN patients p ON p.patient_id=pr.patient_id JOIN doctors d ON d.doctor_id=pr.doctor_id JOIN users u ON u.user_id=d.user_id JOIN departments dep ON dep.department_id=d.department_id JOIN consultations c ON c.consultation_id=pr.consultation_id WHERE pr.prescription_id=?");$stmt->execute([$id]);$rx=$stmt->fetch();if(!$rx||!can_view_patient((int)$rx['patient_id'])){http_response_code(403);die('Prescription not found or access denied.');}$stmt=db()->prepare('SELECT pi.*,m.generic_name,m.brand_name,m.strength,m.dosage_form FROM prescription_items pi JOIN medicines m ON m.medicine_id=pi.medicine_id WHERE pi.prescription_id=?');$stmt->execute([$id]);$items=$stmt->fetchAll();$hospital=setting('hospital_name','MediFlow Hospital');
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($rx['prescription_number'])?></title><style>body{font-family:Arial,sans-serif;color:#172033;margin:0;background:#eef2f7}.sheet{max-width:850px;margin:24px auto;background:#fff;padding:38px;min-height:1050px;box-shadow:0 10px 35px #0002}.head{display:flex;justify-content:space-between;border-bottom:3px solid #2563eb;padding-bottom:18px}.logo{font-size:27px;font-weight:800;color:#2563eb}.muted{color:#667085;font-size:13px}.meta{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;padding:18px 0;border-bottom:1px solid #ddd}.label{font-size:11px;text-transform:uppercase;color:#667085}.rx{font-size:38px;color:#2563eb;margin:24px 0 12px}.medicine{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:12px;padding:13px 0;border-bottom:1px solid #eee}.advice{margin-top:28px;padding:16px;background:#f8fafc;border-radius:10px}.footer{margin-top:70px;display:flex;justify-content:space-between}.sign{text-align:center;border-top:1px solid #333;padding-top:8px;min-width:220px}.actions{max-width:850px;margin:18px auto;text-align:right}.btn{padding:10px 15px;background:#2563eb;color:#fff;border:0;border-radius:8px;cursor:pointer}@media print{body{background:#fff}.sheet{box-shadow:none;margin:0;max-width:none}.actions{display:none}}</style></head><body><div class="actions"><button class="btn" onclick="window.print()">Print prescription</button></div><main class="sheet"><div class="head"><div><div class="logo">✚ <?=e($hospital)?></div><div class="muted"><?=e(setting('hospital_address',''))?> · <?=e(setting('hospital_phone',''))?></div></div><div style="text-align:right"><strong><?=e($rx['doctor_name'])?></strong><div class="muted"><?=e($rx['qualification']??'')?> · <?=e($rx['specialization'])?><br><?=e($rx['department_name'])?></div></div></div><div class="meta"><div><div class="label">Patient</div><strong><?=e($rx['patient_name'])?></strong><div class="muted"><?=e($rx['patient_code'])?></div></div><div><div class="label">Age / Blood group</div><strong><?=e($rx['date_of_birth']?date_diff(date_create($rx['date_of_birth']),date_create('today'))->y.' years':'—')?> · <?=e($rx['blood_group']??'Unknown')?></strong></div><div><div class="label">Date / Prescription</div><strong><?=format_date($rx['issued_at'])?></strong><div class="muted"><?=e($rx['prescription_number'])?> · v<?=$rx['version_number']?></div></div></div><p><strong>Diagnosis:</strong> <?=e($rx['diagnosis']??'Not specified')?></p><div class="rx">℞</div><?php foreach($items as $i=>$item):?><div class="medicine"><div><strong><?=($i+1)?>. <?=e($item['generic_name'].' '.($item['strength']??''))?></strong><div class="muted"><?=e($item['brand_name']??'')?> <?=e($item['dosage_form']??'')?></div></div><div><div class="label">Dosage</div><?=e($item['dosage']??'—')?></div><div><div class="label">Frequency</div><?=e($item['frequency']??'—')?></div><div><div class="label">Duration</div><?=e($item['duration']??'—')?></div><div style="grid-column:1/-1" class="muted">Timing: <?=e($item['timing']??'—')?> · Instructions: <?=e($item['instructions']??'—')?></div></div><?php endforeach;?><?php if(!$items):?><p>No medicines prescribed.</p><?php endif;?><div class="advice"><strong>Advice</strong><p><?=nl2br(e($rx['general_advice']??'No additional advice.'))?></p></div><?php if($rx['allergy_override_reason']):?><div class="advice"><strong>Allergy override note</strong><p><?=e($rx['allergy_override_reason'])?></p></div><?php endif;?><div class="footer"><div class="muted">Generated by MediFlow<br>This document is valid with the doctor's authorization.</div><div class="sign"><strong><?=e($rx['doctor_name'])?></strong><br><span class="muted">Doctor signature</span></div></div></main></body></html>
